package com.anssa8bu.ssafy.common.redis;

import com.anssa8bu.ssafy.support.IntegrationTestBase; import com.anssa8bu.ssafy.common.redis.dto.*; import com.anssa8bu.ssafy.common.redis.lease.AtomicLeaseStore; import com.anssa8bu.ssafy.common.redis.repository.*; import com.anssa8bu.ssafy.common.redis.service.RedisRateLimiter; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.data.redis.core.StringRedisTemplate; import java.time.*; import java.util.*; import java.util.concurrent.*; import static org.assertj.core.api.Assertions.*;
class RedisInfrastructureIntegrationTest extends IntegrationTestBase {@Autowired StringRedisTemplate redis;@Autowired RedisKeyGenerator keys;@Autowired SessionCacheRepository sessions;@Autowired AtomicLeaseStore leases;@Autowired SseEventReplayRepository sse;@Autowired IdempotencyCacheRepository idempotency;@Autowired RedisRateLimiter rateLimiter;@Autowired DevicePresenceRepository presence;@Autowired PurgeLeaseCacheRepository purgeLeases;@Autowired TrainingProfileCacheRepository activeProfile;@Autowired RedisTtlProperties ttl;UUID id;@BeforeEach void init(){id=UUID.randomUUID();}@AfterEach void clean(){redis.delete(List.of(keys.session(id),keys.trainingLease(id),keys.sseEvents(id),keys.idempotency("gpu","key"),keys.rateLimit("gpu","claim"),keys.devicePresence(id),keys.purgeLease(id)));}
 @Test void dtoRoundTripAndTtl(){Instant expiry=Instant.now().plusSeconds(5);sessions.save(id,new SessionCache(1,id,UUID.randomUUID(),expiry,false),Duration.ofMillis(250));assertThat(sessions.find(id)).isPresent();awaitMissing(()->sessions.find(id).isEmpty());}
 @Test void leaseIsAtomicAndOwnerChecked()throws Exception{String key=keys.trainingLease(id);ExecutorService pool=Executors.newFixedThreadPool(8);try{List<Future<Boolean>> f=new ArrayList<>();for(int i=0;i<8;i++)f.add(pool.submit(()->leases.acquire(key,"owner",Duration.ofSeconds(5))));assertThat(f.stream().filter(x->{try{return x.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isOne();assertThat(leases.renew(key,"wrong",Duration.ofSeconds(5))).isFalse();assertThat(leases.renew(key,"owner",Duration.ofSeconds(5))).isTrue();assertThat(leases.release(key,"wrong")).isFalse();assertThat(leases.release(key,"owner")).isTrue();}finally{pool.shutdownNow();}}
 @Test void sseReplaysInOrderAndIsolatesUsers(){UUID other=UUID.randomUUID();try{var a=new SseEventCache(1,"a","DONE","1",Instant.now(),Map.of("n",1));var b=new SseEventCache(1,"b","DONE","2",Instant.now(),Map.of("n",2));String first=sse.append(id,a,Duration.ofMinutes(1),10);sse.append(id,b,Duration.ofMinutes(1),10);sse.append(other,a,Duration.ofMinutes(1),10);assertThat(sse.after(id,first)).extracting(SseEventCache::eventId).containsExactly("b");assertThat(sse.after(other,null)).hasSize(1);}finally{redis.delete(keys.sseEvents(other));}}
 @Test void idempotencyReservationIsAtomic(){assertThat(idempotency.reserve("gpu","key","hash",Duration.ofMinutes(1))).isTrue();assertThat(idempotency.reserve("gpu","key","other",Duration.ofMinutes(1))).isFalse();assertThat(idempotency.find("gpu","key")).contains("hash");}
 @Test void rateLimitCounterExpiresAsOneWindow(){assertThat(rateLimiter.allow("gpu","claim",2,Duration.ofSeconds(1))).isTrue();assertThat(rateLimiter.allow("gpu","claim",2,Duration.ofSeconds(1))).isTrue();assertThat(rateLimiter.allow("gpu","claim",2,Duration.ofSeconds(1))).isFalse();assertThat(redis.getExpire(keys.rateLimit("gpu","claim"))).isPositive();}
 @Test void remainingRepositoriesRoundTripAndExpire(){Instant at=Instant.parse("2026-09-08T00:00:00Z");presence.save(id,new DevicePresence(1,id,at),Duration.ofMillis(250));purgeLeases.save(id,new PurgeLeaseCache(1,id,0,"worker","c".repeat(64),at),Duration.ofMillis(250));assertThat(presence.find(id)).contains(new DevicePresence(1,id,at));assertThat(purgeLeases.find(id)).contains(new PurgeLeaseCache(1,id,0,"worker","c".repeat(64),at));assertThat(redis.getExpire(keys.devicePresence(id),TimeUnit.MILLISECONDS)).isBetween(1L,250L);awaitMissing(()->presence.find(id).isEmpty()&&purgeLeases.find(id).isEmpty());}
 @Test void activeTrainingProfileCacheUsesConfiguredTtl(){var cached=new ActiveTrainingProfileCache(1,UUID.randomUUID(),"umi-act-default",1,"a".repeat(64),Map.of("epochs",100));try{activeProfile.save(cached,ttl.trainingProfile());assertThat(activeProfile.find()).contains(cached);assertThat(redis.getExpire(keys.activeTrainingProfile(),TimeUnit.SECONDS)).isBetween(ttl.trainingProfile().toSeconds()-5,ttl.trainingProfile().toSeconds());}finally{activeProfile.delete();}}
 private void awaitMissing(Callable<Boolean> c){long end=System.nanoTime()+Duration.ofSeconds(3).toNanos();try{while(!c.call()&&System.nanoTime()<end)Thread.sleep(25);assertThat(c.call()).isTrue();}catch(Exception e){throw new RuntimeException(e);}}
}
